{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']

    # Validate nodes and core distance coverage
    node_set = set(nodes)
    if len(node_set) != len(nodes):
        raise ValueError('Duplicate node names')
    if set(core_dist.keys()) != node_set:
        raise ValueError('core_distance keys do not match nodes')

    # Build mutual reachability edges
    edges = []
    for u, v, d in distances:
        if u not in node_set or v not in node_set:
            raise ValueError(f'Unknown node in distance: {u} or {v}')
        if u == v:
            continue
        # Canonicalize undirected endpoints (lexicographic order)
        if u > v:
            u, v = v, u
        weight = max(core_dist[u], core_dist[v], d)
        edges.append((weight, u, v))

    # Sort by weight, then u, then v (deterministic tie-breaking)
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find (Disjoint Set Union) with path compression and union by rank
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    required_edges = len(nodes) - 1

    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == required_edges:
                break

    if len(mst_edges) != required_edges:
        raise ValueError('Disconnected graph: cannot form MST')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }
